export const COMPLIANCE_NOTICE = 'Compliance varies by exact product, use, radio module, composition, claims, origin, state and current notification. These playbooks are data-quality starting points, not legal advice. The accountable operator must verify current Indian central/state requirements and retain authoritative evidence before approval.';

export const findPlaybook = (query) => {
  const needle = String(query || '').trim().toLowerCase();
  if (!needle) return null;
  return CATEGORY_PLAYBOOKS.find((playbook) => playbook.id === needle || playbook.name.toLowerCase() === needle || playbook.aliases.some((alias) => alias.toLowerCase().includes(needle) || needle.includes(alias.toLowerCase()))) || null;
};
